const host=u=>{try{return new URL(u).hostname.replace(/^www\./,'')}catch{return ''}};
function save(skipCloud=false){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{showToast('本地存储空间不足，请换一张较小的壁纸');}if(!skipCloud)scheduleCloudSync();}
function restoreSitesToFolders(){
  let changed=false;
  if(!Array.isArray(state.categories)){state.categories=defaultCategories.map(category=>({...category}));changed=true;}
  if(!Array.isArray(state.bookmarks)){state.bookmarks=[];changed=true;}
  const siteHost=value=>{try{return new URL(value).hostname.replace(/^www\./,'').toLowerCase();}catch{return '';}};
  const requestedHosts=new Set(['youtube.com','mail.google.com','yuque.com','notion.so','grok.com','chatgpt.com','github.com','gemini.google.com','huggingface.co']);
  if(!state.defaultSitesFolderMigrationV4){
    const sitesToRestore=state.defaultSitesFolderMigrationV3?initial.filter(site=>requestedHosts.has(siteHost(site.url))):initial;
    for(const site of sitesToRestore){
      const existing=state.bookmarks.find(bookmark=>bookmark&&siteHost(bookmark.url)===siteHost(site.url));
      if(existing)continue;
      if(!state.categories.some(item=>item&&item.name===site.category)){
        const category=defaultCategories.find(item=>item.name===site.category);
        state.categories.push(category?{...category}:{name:site.category,icon:'✦'});
      }
      state.bookmarks.push({...site,home:site.home===true});
      changed=true;
    }
    state.defaultSitesFolderMigrationV3=true;
    state.defaultSitesFolderMigrationV4=true;
    changed=true;
  }
  if(!state.defaultHomepageMigrationV1){
    for(const site of initial.filter(item=>requestedHosts.has(siteHost(item.url)))){
      const existing=state.bookmarks.find(bookmark=>bookmark&&siteHost(bookmark.url)===siteHost(site.url));
      if(existing&&!existing.home){existing.home=true;changed=true;}
    }
    state.defaultHomepageMigrationV1=true;
    changed=true;
  }
  const remaining=state.bookmarks.filter(bookmark=>siteHost(bookmark?.url)!=='nav.eooce.com');
  if(remaining.length!==state.bookmarks.length){state.bookmarks=remaining;changed=true;}
  if(changed)save();
}
restoreSitesToFolders();
